<script setup lang="ts">
import { ref,onMounted,computed } from 'vue'
import { NButton,NDrawer,NDrawerContent,NInput } from 'naive-ui'
import { api,post,rows,name,ident,str,pretty,type Row } from '../api'
import Notice from '../components/Notice.vue'
import AppIcon from '../components/AppIcon.vue'
import FormDialog,{type FormField} from '../components/FormDialog.vue'
import ConfirmDialog from '../components/ConfirmDialog.vue'
import { t, localized, renderText, formatNumber } from '../i18n'
const actionBusy=ref(false),projects=ref<Row[]>([]),discovered=ref<Row[]>([]),error=ref<unknown>(''),busy=ref(false),selected=ref<Row|null>(null),files=ref<{path:string;content:string}[]>([]),preview=ref<Row|null>(null),form=ref(false),confirm=ref(false),feedback=ref<unknown>('')
const savedFiles=ref(''),fileBusy=ref(false),previewBusy=ref(false),dirty=computed(()=>JSON.stringify(files.value)!==savedFiles.value)
const fields=computed<FormField[]>(()=>[{key:'name',label:t('compose.name'),required:true},{key:'workdir',label:t('compose.workdir'),required:true,placeholder:'/srv/my-project'},{key:'config_paths',label:t('compose.configPaths'),type:'textarea',required:true,placeholder:'/srv/my-project/compose.yaml'},{key:'env_files',label:t('compose.envFiles'),type:'textarea'},{key:'profiles',label:t('compose.profiles')}])
async function load(){busy.value=true;try{projects.value=rows(await api('/compose/projects'));discovered.value=rows(await api('/compose/discover'));error.value=''}catch(e){error.value=e}finally{busy.value=false}}
async function submit(v:Row){return post('/compose/import',{...v,config_paths:str(v.config_paths).split('\n').filter(Boolean),env_files:String(v.env_files??'').split('\n').filter(Boolean),profiles:String(v.profiles??'').split(',').map(x=>x.trim()).filter(Boolean),confirm:true})}
async function inspect(row:Row){error.value='';try{const response=await api(`/compose/projects/${ident(row)}`);selected.value=(response.project??response) as Row;files.value=(response.files??[]) as {path:string;content:string}[];savedFiles.value=JSON.stringify(files.value);preview.value=null}catch(e){error.value=e}}
async function check(){if(dirty.value||fileBusy.value){error.value=localized('compose.saveBeforePreview');return}previewBusy.value=true;error.value='';preview.value=null;try{preview.value=await post(`/compose/projects/${ident(selected.value!)}/preview`)}catch(e){error.value=e}finally{previewBusy.value=false}}
async function save(){if(fileBusy.value||actionBusy.value)return;fileBusy.value=true;error.value='';try{await api(`/compose/projects/${ident(selected.value!)}/files`,{method:'PUT',body:JSON.stringify({revision:selected.value?.revision,files:files.value})});preview.value=null;feedback.value=localized('compose.filesSaved');await inspect(selected.value!)}catch(e){error.value=e}finally{fileBusy.value=false}}
async function deploy(){if(actionBusy.value)return;if(dirty.value||!preview.value){error.value=localized('compose.previewBeforeDeploy');return}actionBusy.value=true;error.value='';try{await post(`/compose/projects/${ident(selected.value!)}/deploy`,{confirm:true,revision:preview.value.revision});confirm.value=false;feedback.value=localized('compose.deploySubmitted');await load()}catch(e){error.value=e}finally{actionBusy.value=false}}
onMounted(load)
</script>
<template><div class="toolbar"><p class="muted">{{ t('compose.linkInfo') }}</p><div class="actions"><n-button @click="load" :loading="busy"><AppIcon name="refresh"/>{{ t('compose.rediscover') }}</n-button><n-button type="primary" @click="form=true"><AppIcon name="plus"/>{{ t('compose.import') }}</n-button></div></div><Notice :error="error"/><p v-if="feedback" class="notice success">{{ renderText(feedback) }}</p><section class="panel table-panel"><div class="panel-title"><h3>{{ t('compose.managedProjects') }} <span class="count">{{ formatNumber(projects.length) }}</span></h3><span class="eyebrow">{{ t('compose.workspaces') }}</span></div><div class="table-scroll"><table><thead><tr><th>{{ t('compose.project') }}</th><th>{{ t('compose.workdir') }}</th><th>{{ t('compose.sourceStatus') }}</th><th>{{ t('compose.actions') }}</th></tr></thead><tbody><tr v-for="project in projects" :key="ident(project)"><td><strong>{{ name(project) }}</strong><code>{{ ident(project) }}</code></td><td>{{ str(project.workdir) }}</td><td>{{ project.source_type === 'local' ? t('compose.sourceLocal') : project.source_type === 'candidate' ? t('compose.sourceCandidate') : str(project.source_type) }} · {{ project.unavailable?t('compose.unavailable'):project.changed?t('compose.changed'):t('compose.unchanged') }}</td><td><n-button size="small" @click="inspect(project)">{{ t('compose.manage') }}</n-button></td></tr></tbody></table></div><Notice :busy="busy" :empty="!busy&&!projects.length"/></section><section class="panel section-gap"><div class="panel-title"><h3>{{ t('compose.discovery') }}</h3><span class="eyebrow">{{ t('compose.discoveryCaption') }}</span></div><p class="muted">{{ t('compose.discoveryInfo') }}</p><pre v-if="discovered.length" class="json-block">{{ pretty(discovered) }}</pre><div v-else class="quiet-empty">{{ t('compose.noDiscovery') }}</div></section><n-drawer :show="Boolean(selected)" :width="'min(850px,100vw)'" @update:show="v=>!v&&(selected=null)"><n-drawer-content :title="t('compose.drawerTitle')" closable><template v-if="selected"><Notice :error="error"/><pre class="json-block">{{ pretty(selected) }}</pre><h3>{{ t('compose.editConfig') }}</h3><p class="muted">{{ t('compose.editInfo') }}</p><div v-if="dirty" class="notice warning" role="status">{{ t('compose.unsaved') }}</div><div v-for="file in files" :key="file.path" class="form-field"><label>{{ file.path }}</label><n-input class="code-editor" v-model:value="file.content" :disabled="fileBusy||actionBusy" type="textarea" :autosize="{minRows:10,maxRows:25}" :input-props="{'aria-label':t('compose.configAria', { path: file.path }),spellcheck:false}" @update:value="preview=null"/></div><Notice :empty="!files.length"/><div class="actions section-gap"><n-button :disabled="!dirty||actionBusy" :loading="fileBusy" @click="save">{{ t('compose.saveFiles') }}</n-button><n-button :disabled="dirty||fileBusy||!files.length" :loading="previewBusy" @click="check">{{ t('compose.validatePreview') }}</n-button><n-button type="primary" :disabled="dirty||fileBusy||previewBusy||!preview" @click="error='';confirm=true">{{ t('compose.deploy') }}</n-button></div><pre v-if="preview" class="json-block">{{ pretty(preview) }}</pre></template></n-drawer-content></n-drawer><FormDialog v-model:show="form" :title="t('compose.importTitle')" :fields="fields" :submit="submit" :description="t('compose.importInfo')" @saved="load"/><ConfirmDialog v-model:show="confirm" :title="t('compose.deployTitle')" :error="error" :busy="actionBusy" :detail="t('compose.deployWarning')" @confirm="deploy"/></template>
